4431: # A probe of the claude launcher (`claude auth status`, `claude --version`) in the child
4432: # environment of $Auth (D3): its start info's block is CLEARED and filled from
4433: # Get-ClaudeChildEnvironment, then started through Start-ProbeProcess (never with a host marker).
4434: # Nothing on stdin; stdout and stderr as UTF-8. { Started; Why; Exit (-1 when it did not exit);
4435: # TimedOut; Out; Err }.
4436: function Invoke-ClaudeProbe {
4437:     param([string]$Launcher, [string]$Arguments, [int]$TimeoutSec = 15, [string]$Auth = 'subscription')
4438:     $r = [pscustomobject]@{ Started = $false; Why = ''; Exit = -1; TimedOut = $false; Out = ''; Err = '' }
4439:     $p = $null
4440:     try {
4441:         # (the block reads $Launcher, $Arguments and $Auth of this function: Start-ProbeProcess runs it
4442:         # in a child scope of its own, which has none of them)
4443:         $start = Start-ProbeProcess -Make {
4444:             $cpsi = New-ProbeStartInfo -Launcher $Launcher -Arguments $Arguments
4445:             $cblock = $cpsi.EnvironmentVariables
4446:             $cblock.Clear()
4447:             $cce = Get-ClaudeChildEnvironment -Auth $Auth
4448:             foreach ($ck in @($cce.Env.Keys)) { $cblock[[string]$ck] = [string]$cce.Env[$ck] }
4449:             $cpsi
4450:         }
4451:         if ($start.Skipped) { $r.Why = [string]$start.Skipped; return $r }
4452:         $p = $start.Proc
4453:     } catch { $r.Why = ConvertTo-OneLine $_.Exception.Message; return $r }
4454:     $r.Started = $true
4455:     try {
4456:         try { $p.StandardInput.Close() } catch { }
4457:         $outTask = $p.StandardOutput.ReadToEndAsync()
4458:         $errTask = $p.StandardError.ReadToEndAsync()
4459:         if (-not $p.WaitForExit($TimeoutSec * 1000)) {
4460:             $null = Stop-ProcessTree -Process $p
4461:             $r.TimedOut = $true
4462:             return $r
4463:         }
4464:         $p.WaitForExit()
4465:         $null = $outTask.Wait(5000)
4466:         $null = $errTask.Wait(5000)
4467:         $r.Exit = $p.ExitCode
4468:         $r.Out = [string]$outTask.Result
4469:         $r.Err = [string]$errTask.Result
4470:         return $r
4471:     } finally {
4472:         $p.Dispose()
4473:     }
4474: }
