4403: # The child environment of a claude process for $Auth, from THIS process's environment (read-only
4404: # here): { Auth; Env (name -> value, sorted; the allowed variables plus the set ones); Names
4405: # (string[], sorted ordinal - the ledger's engine_run.child_env_allowed; never a value); Removed
4406: # (string[]: the names of this process's variables the child does not get) }. One builder for the
4407: # preflight, the version probe and every turn (D3 / F03-3).
4408: function Get-ClaudeChildEnvironment {
4409:     param([string]$Auth = 'subscription')
4410:     if ($script:ClaudeAuthModes -notcontains $Auth) { $Auth = 'subscription' }
4411:     $pass = ([string](Get-TestHookValue 'CODEX_CONSULT_TEST_CHILD_ENV_PASS')).Trim()
4412:     if ($pass -and ($pass -notmatch '^[A-Za-z][A-Za-z0-9_]{3,}$' -or $pass.ToUpperInvariant() -match '^(ANTHROPIC|CLAUDE|CODEX_CONSULT)')) { $pass = '' }
