4414:     $envOut = New-Object 'System.Collections.Generic.SortedDictionary[string,string]' ($cmp)
4415:     $removed = New-Object System.Collections.Generic.List[string]
4416:     $all = [Environment]::GetEnvironmentVariables()
4417:     foreach ($k in @($all.Keys)) {
4418:         $n = [string]$k
4419:         if (-not $n -or $n.Contains('=') -or $envOut.ContainsKey($n)) { continue }
4420:         if (Test-ClaudeChildEnvName -Name $n -Auth $Auth -PassPrefix $pass) { $envOut[$n] = [string]$all[$k] }
4421:         elseif (-not $script:ClaudeChildEnvSet.Contains($n) -and -not $removed.Contains($n)) { $removed.Add($n) }
4422:     }
4423:     foreach ($k in @($script:ClaudeChildEnvSet.Keys)) { $envOut[[string]$k] = [string]$script:ClaudeChildEnvSet[$k] }
4424:     $names = [string[]]@($envOut.Keys)
4425:     [Array]::Sort($names, [StringComparer]::Ordinal)
4426:     $rm = [string[]]$removed.ToArray()
4427:     [Array]::Sort($rm, [StringComparer]::Ordinal)
4428:     return [pscustomobject]@{ Auth = $Auth; Env = $envOut; Names = $names; Removed = $rm }
4429: }
