 4596: # (item 1) The reply schema as `claude --json-schema` takes it: its TEXT, whitespace outside strings
 4597: # removed (one line; the strings keep theirs). '' when the file cannot be read.
 4598: function Get-ClaudeSchemaText {
 4599:     param([string]$Path)
 4600:     $text = ''
 4601:     try { $text = [IO.File]::ReadAllText($Path, $script:Utf8NoBom) } catch { return '' }
 4602:     $sb = New-Object System.Text.StringBuilder
 4603:     $inStr = $false
 4604:     $esc = $false
 4605:     foreach ($ch in $text.ToCharArray()) {
 4606:         if ($inStr) {
 4607:             [void]$sb.Append($ch)
 4608:             if ($esc) { $esc = $false } elseif ($ch -eq [char]'\') { $esc = $true } elseif ($ch -eq [char]'"') { $inStr = $false }
 4609:             continue
 4610:         }
 4611:         if ($ch -eq [char]'"') { $inStr = $true; [void]$sb.Append($ch); continue }
 4612:         if ([char]::IsWhiteSpace($ch) -or $ch -eq [char]0xFEFF) { continue }
 4613:         [void]$sb.Append($ch)
 4614:     }
 4615:     return $sb.ToString()
 4616: }
