 4618: # (item 1) The argv of one claude turn (after the launcher), from the turn options: print mode, the
 4619: # stream-json events, the restricted read-only session (--restricted --strict-mcp-config
 4620: # --disable-slash-commands --tools Read,Grep,Glob --permission-mode dontAsk), the model (the
 4621: # roster's on a new thread, the RESOLVED id on every later turn - D4), --effort when one is sent (the
 4622: # repair sends low), the schema TEXT (--json-schema: structured mode with transport native and every
 4623: # repair / denial-retry / continuation turn of such a run), --max-turns with -MaxModelSteps (D8),
 4624: # --add-dir for a collab directory, brief or artifact outside the repository, then the session:
 4625: # --session-id <the minted uuid> on a new thread (known before the first byte - item 2), --resume
 4626: # <thread> to continue one (every secondary turn), --resume <parent> --fork-session to fork. The
 4627: # prompt travels on stdin, never in argv.
 4628: function Get-ClaudeArgs {
 4629:     param($Turn)
 4630:     $a = @('-p', '--output-format', 'stream-json', '--verbose', '--restricted', '--strict-mcp-config', '--disable-slash-commands', '--tools', $script:ClaudeToolsArg, '--permission-mode', $script:ClaudePermissionMode, '--model', [string]$Turn.Model)
 4631:     if ($null -ne $Turn.Effort -and ([string]$Turn.Effort).Trim()) { $a += @('--effort', [string]$Turn.Effort) }
 4632:     if ($Turn.Schema) { $a += @('--json-schema', (Get-ClaudeSchemaText -Path ([string]$Turn.Schema))) }
 4633:     if ([int]$Turn.MaxSteps -gt 0) { $a += @('--max-turns', [string][int]$Turn.MaxSteps) }
 4634:     foreach ($d in @(Get-PropertyValue $Turn 'AddDirs' @())) { if ($d) { $a += @('--add-dir', [string]$d) } }
 4635:     $thread = [string]$Turn.Thread
 4636:     if ($thread) {
 4637:         $a += @('--resume', $thread)
 4638:         if ([string]$Turn.Mode -eq 'fork') { $a += '--fork-session' }
 4639:     } else {
 4640:         $nt = [string](Get-PropertyValue $Turn 'NewThread' '')
 4641:         if ($nt) { $a += @('--session-id', $nt) }
 4642:     }
 4643:     return , ([string[]]$a)
 4644: }
