 4652: # (wave 29) One argument of an engine whose CLI parses its command line by the C runtime rules
 4653: # (claude): a bare token when safe, else double-quoted with every quote as \" and the backslashes
 4654: # before a quote (and at the end) doubled - read the same by every Windows argv parser (the one-line
 4655: # schema text of --json-schema is full of quotes), and safe through a cmd.exe shim as long as the
 4656: # value holds no % and no cmd.exe operator outside its quotes.
 4657: function ConvertTo-CrtArg {
 4658:     param([string]$Value)
 4659:     if ($Value -and $Value -match '^[A-Za-z0-9_.\-:\\/=]+$') { return $Value }
 4660:     $sb = New-Object System.Text.StringBuilder
 4661:     [void]$sb.Append('"')
 4662:     $bs = 0
 4663:     foreach ($ch in ([string]$Value).ToCharArray()) {
 4664:         if ($ch -eq [char]'\') { $bs++; continue }
 4665:         if ($ch -eq [char]'"') { [void]$sb.Append('\', 2 * $bs + 1); [void]$sb.Append('"'); $bs = 0; continue }
 4666:         if ($bs -gt 0) { [void]$sb.Append('\', $bs); $bs = 0 }
 4667:         [void]$sb.Append($ch)
 4668:     }
 4669:     if ($bs -gt 0) { [void]$sb.Append('\', 2 * $bs) }
 4670:     [void]$sb.Append('"')
 4671:     return $sb.ToString()
 4672: }
