 4674: # A Unix time (seconds, or milliseconds when it is that large) or an ISO string as a DateTimeOffset
 4675: # (UTC), $null when it is neither.
 4676: function ConvertFrom-ClaudeResetTime {
 4677:     param($Value)
 4678:     if ($null -eq $Value) { return $null }
 4679:     $n = [double]0
 4680:     if (($Value -is [int] -or $Value -is [long] -or $Value -is [double] -or $Value -is [decimal]) -or ($Value -is [string] -and $Value -match '^[0-9]{9,14}(\.[0-9]+)?$' -and [double]::TryParse($Value, [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$n))) {
 4681:         if (-not ($Value -is [string])) { $n = [double]$Value }
 4682:         if ($n -gt 1e12) { $n = $n / 1000 }
 4683:         if ($n -lt 1e9 -or $n -gt 1e10) { return $null }
 4684:         try { return [DateTimeOffset]::FromUnixTimeSeconds([long][Math]::Floor($n)) } catch { return $null }
 4685:     }
 4686:     if ($Value -is [string]) {
 4687:         $d = [DateTimeOffset]::MinValue
 4688:         if ($Value -match '^[0-9]{4}-[0-9]{2}-[0-9]{2}T' -and [DateTimeOffset]::TryParse($Value, $script:Invariant, [System.Globalization.DateTimeStyles]::AssumeUniversal, [ref]$d)) { return $d.ToUniversalTime() }
 4689:     }
 4690:     if ($Value -is [datetime]) { return ([DateTimeOffset]([datetime]::SpecifyKind($Value, [DateTimeKind]::Utc))) }
 4691:     return $null
 4692: }
