 4694: # One claude event stream (stdout of `claude -p --output-format stream-json --verbose`: one JSON
 4695: # object per line - obs), parsed tolerantly into the normalized turn record (item 3):
 4696: #   InitCount        the `system`/`init` events (one per `claude -p` run); every one is evidence
 4697: #   InitThread, InitModel   the FIRST init's session_id and model
 4698: #   InitThreads, InitModels, InitModes, InitKeySources   the distinct values over every init
 4699: #   InitTools        the union of their tools; InitMcp the names of their MCP servers (any entry
 4700: #                    counts); InitCwd the first init's cwd
 4701: #   ResultCount      number of `result` events (exactly one is a well-formed stream)
 4702: #   Malformed        '' or why the stream is malformed: a line that does not parse as a JSON object
 4703: #                    (the LAST non-empty line may be partial only with -AllowPartialLast - a killed
 4704: #                    turn or a non-zero exit, F10-2), more than one result, a result that is not the
 4705: #                    last event, two init events that name different sessions
 4706: #   HasResult; Thread (result.session_id); Subtype; IsError; Response (result.result - its text);
 4707: #   Error (the result text of a failed result, else its errors[]); HasStructured; StructuredJson
 4708: #   (result.structured_output serialized compactly); CostUsd (total_cost_usd - notional on a
 4709: #   subscription, kept local); NumTurns; StopReason
 4710: #   Usage            { input_tokens (input + cache read + cache creation: the whole prompt, as
 4711: #                    codex counts it), cached_input_tokens (cache_read_input_tokens),
 4712: #                    cache_creation_input_tokens, output_tokens, reasoning_output_tokens ($null:
 4713: #                    not reported), total_tokens } or $null
 4714: #   ModelUsage       the keys of result.modelUsage; MainModel the key with the most output tokens
 4715: #   AssistantModels  the distinct message.model of the assistant events (<synthetic> left out)
 4716: #   Denials          result.permission_denials as { Tool; Target (file_path | path | pattern) };
 4717: #                    DenialCount; ToolName / DeniedAction the first denial as "<tool> <target>"
 4718: #   RateLimit        the most severe rate_limit_event's info object as the CLI wrote it (D6: recorded
 4719: #                    raw); RateLimitStatus; RateLimitRejected (a status that rejects); RateLimitType;
 4720: #                    RateLimitReset (DateTimeOffset or $null) - field names read defensively
 4721: #   Compactions      the system/compact_boundary events
 4722: function Read-ClaudeEvents {
 4723:     param([string]$Path, [switch]$AllowPartialLast)
 4724:     $r = [pscustomobject]@{
 4725:         InitCount = 0; InitThread = ''; InitModel = ''; InitThreads = [string[]]@(); InitModels = [string[]]@(); InitModes = [string[]]@(); InitKeySources = [string[]]@(); InitTools = [string[]]@(); InitMcp = [string[]]@(); InitCwd = ''
 4726:         ResultCount = 0; Malformed = ''; HasResult = $false; Thread = ''; Subtype = ''; IsError = $false; Response = ''; Error = ''; HasStructured = $false; StructuredJson = ''
 4727:         CostUsd = $null; NumTurns = $null; StopReason = ''; Usage = $null; ModelUsage = [string[]]@(); MainModel = ''; AssistantModels = [string[]]@()
 4728:         Denials = [object[]]@(); DenialCount = 0; ToolName = ''; DeniedAction = ''
 4729:         RateLimit = $null; RateLimitStatus = ''; RateLimitRejected = $false; RateLimitType = ''; RateLimitReset = $null; Compactions = 0
 4730:     }
 4731:     $text = $(if ($Path) { Read-SharedText -Path $Path } else { '' })
 4732:     if (-not $text) { return $r }
 4733:     $lines = @($text -split "`r?`n")
 4734:     $lastIdx = -1
 4735:     for ($i = $lines.Count - 1; $i -ge 0; $i--) { if ($lines[$i].Trim()) { $lastIdx = $i; break } }
 4736:     $result = $null
 4737:     $resultLine = -1
 4738:     $afterResult = $false
 4739:     $threads = New-Object System.Collections.Generic.List[string]
 4740:     $models = New-Object System.Collections.Generic.List[string]
 4741:     $modes = New-Object System.Collections.Generic.List[string]
 4742:     $keySources = New-Object System.Collections.Generic.List[string]
 4743:     $tools = New-Object System.Collections.Generic.List[string]
 4744:     $mcp = New-Object System.Collections.Generic.List[string]
 4745:     $amodels = New-Object System.Collections.Generic.List[string]
 4746:     $rlRank = -1
 4747:     $addU = { param($list, [string]$v) if (-not $list.Contains($v)) { $list.Add($v) } }
 4748:     for ($i = 0; $i -lt $lines.Count; $i++) {
 4749:         $t = $lines[$i].Trim()
 4750:         if (-not $t) { continue }
 4751:         $obj = $null
 4752:         try { $obj = ConvertFrom-Json -InputObject $t } catch { $obj = $null }
 4753:         if ($null -eq $obj -or -not ($obj -is [System.Management.Automation.PSCustomObject])) {
 4754:             if (($i -ne $lastIdx -or -not $AllowPartialLast) -and -not $r.Malformed) { $r.Malformed = "line $($i + 1) is not a JSON object" }
 4755:             continue
 4756:         }
 4757:         if ($null -ne $result) { $afterResult = $true }
 4758:         $type = [string](Get-PropertyValue $obj 'type' '')
 4759:         $sub = [string](Get-PropertyValue $obj 'subtype' '')
 4760:         if ($type -eq 'system' -and $sub -eq 'init') {
 4761:             $r.InitCount++
 4762:             $sid = [string](Get-PropertyValue $obj 'session_id' '')
 4763:             $mdl = [string](Get-PropertyValue $obj 'model' '')
 4764:             if ($r.InitCount -eq 1) { $r.InitThread = $sid; $r.InitModel = $mdl; $r.InitCwd = [string](Get-PropertyValue $obj 'cwd' '') }
 4765:             & $addU $threads $sid
 4766:             & $addU $models $mdl
 4767:             & $addU $modes ([string](Get-PropertyValue $obj 'permissionMode' ''))
 4768:             $ks = Get-PropertyValue $obj 'apiKeySource' $null
 4769:             & $addU $keySources $(if ($null -eq $ks) { '' } else { [string]$ks })
 4770:             foreach ($tn in @(Get-PropertyValue $obj 'tools' @())) { if ($null -ne $tn) { & $addU $tools ([string]$tn) } }
 4771:             foreach ($ms in @(Get-PropertyValue $obj 'mcp_servers' @())) {
 4772:                 if ($null -eq $ms) { continue }
 4773:                 $mn = $(if (Test-IsJsonObject $ms) { [string](Get-PropertyValue $ms 'name' '') } else { [string]$ms })
 4774:                 & $addU $mcp $(if ($mn) { $mn } else { '(unnamed)' })
 4775:             }
 4776:         } elseif ($type -eq 'system' -and $sub -eq 'compact_boundary') {
 4777:             $r.Compactions++
 4778:         } elseif ($type -eq 'assistant') {
 4779:             $msg = Get-PropertyValue $obj 'message' $null
 4780:             $am = [string](Get-PropertyValue $msg 'model' '')
 4781:             if ($am -and $am -cne '<synthetic>') { & $addU $amodels $am }
 4782:         } elseif ($type -eq 'rate_limit_event') {
 4783:             $info = Get-PropertyValue $obj 'rate_limit_info' $null
 4784:             if (-not (Test-IsJsonObject $info)) { $info = $obj }
 4785:             $st = [string](Get-PropertyValue $info 'status' '')
 4786:             $rank = $(if ($st -match '(?i)reject') { 2 } elseif ($st -match '(?i)warn') { 1 } else { 0 })
 4787:             if ($rank -ge $rlRank) {
 4788:                 $rlRank = $rank
 4789:                 $r.RateLimit = $info
 4790:                 $r.RateLimitStatus = ConvertTo-ClaudeToken $st
 4791:                 $r.RateLimitType = ConvertTo-ClaudeToken (Get-PropertyValue $info 'rateLimitType' (Get-PropertyValue $info 'rate_limit_type' $null))
 4792:                 $reset = Get-PropertyValue $info 'resetsAt' $null
 4793:                 if ($null -eq $reset) { $reset = Get-PropertyValue $info 'resets_at' $null }
 4794:                 if ($null -eq $reset) { $reset = Get-PropertyValue $info 'reset_at' $null }
 4795:                 $r.RateLimitReset = ConvertFrom-ClaudeResetTime $reset
 4796:             }
 4797:             if ($rank -eq 2) { $r.RateLimitRejected = $true }
 4798:         } elseif ($type -eq 'result') {
 4799:             $r.ResultCount++
 4800:             $result = $obj
 4801:             $resultLine = $i
 4802:             $afterResult = $false
 4803:         }
 4804:     }
 4805:     $r.InitThreads = [string[]]@($threads | Where-Object { $_ })
 4806:     $r.InitModels = [string[]]@($models | Where-Object { $_ })
 4807:     $r.InitModes = [string[]]$modes.ToArray()
 4808:     $r.InitKeySources = [string[]]$keySources.ToArray()
 4809:     $r.InitTools = [string[]]$tools.ToArray()
 4810:     $r.InitMcp = [string[]]$mcp.ToArray()
 4811:     $r.AssistantModels = [string[]]$amodels.ToArray()
 4812:     if (-not $r.Malformed -and $r.ResultCount -gt 1) { $r.Malformed = "$($r.ResultCount) result events (exactly one expected)" }
 4813:     if (-not $r.Malformed -and $afterResult) { $r.Malformed = "an event follows the result event (line $($resultLine + 1)); the result must be the last" }
 4814:     if (-not $r.Malformed -and @($r.InitThreads).Count -gt 1) { $r.Malformed = "the init events name $(@($r.InitThreads).Count) sessions ($(@($r.InitThreads) -join ', '))" }
 4815:     if ($null -ne $result) {
 4816:         $r.HasResult = $true
 4817:         $r.Thread = [string](Get-PropertyValue $result 'session_id' '')
 4818:         $r.Subtype = [string](Get-PropertyValue $result 'subtype' '')
 4819:         $r.IsError = ((Get-PropertyValue $result 'is_error' $false) -eq $true)
 4820:         $rt = Get-PropertyValue $result 'result' ''
 4821:         $r.Response = $(if ($rt -is [string]) { $rt } else { '' })
 4822:         $r.StopReason = [string](Get-PropertyValue $result 'stop_reason' '')
 4823:         $nt = Get-PropertyValue $result 'num_turns' $null
 4824:         $ntv = [long]0
 4825:         if ($null -ne $nt -and [long]::TryParse([string]$nt, [ref]$ntv)) { $r.NumTurns = $ntv }
 4826:         $cost = Get-PropertyValue $result 'total_cost_usd' $null
 4827:         $cv = [double]0
 4828:         if ($null -ne $cost -and [double]::TryParse([string]$cost, [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$cv)) { $r.CostUsd = $cv }
 4829:         if ($r.IsError -or ($r.Subtype -and $r.Subtype -ne 'success')) {
 4830:             $r.Error = $r.Response
 4831:             if (-not $r.Error.Trim()) {
 4832:                 $errs = @(@(Get-PropertyValue $result 'errors' @()) | Where-Object { $null -ne $_ } | ForEach-Object { if ($_ -is [string]) { $_ } else { ConvertTo-Json -InputObject $_ -Compress -Depth 6 } })
 4833:                 $r.Error = ($errs -join '; ')
 4834:             }
 4835:         }
 4836:         $so = Get-PropertyValue $result 'structured_output' $null
 4837:         if ($null -ne $so -and $so -is [System.Management.Automation.PSCustomObject]) {
 4838:             $r.HasStructured = $true
 4839:             $r.StructuredJson = ConvertTo-Json -InputObject $so -Compress -Depth 30
 4840:         }

4650: }
