8352: # The concurrency plan of a panel (0.4.x wave 21, D8 - endpoint-aware): members that reach the
8353: # same ENDPOINT run one after another, members of different endpoints at once. The endpoint
8354: # groups come from Get-EndpointGroups over the runners. A group runs 1 member at a time unless
8355: # the roster's top-level "parallel" raises its label (a merged group: the smallest limit of its
8356: # labels); -Cap (-PanelConcurrency) caps the total (0 = no cap, 1 = strictly one after another
8357: # in roster order). $Runners: the members Select-PanelMembers runs (State 'run'), in roster
8358: # order.
8359: # { Groups (object[] of { Labels (string[]); Limit; Positions (int[] roster positions) });
8360: #   GroupOf (hashtable roster position -> group index); Cap; Effective (the most members
8361: #   that can run at once); Text ('at once' | 'one after another' | 'at most <k> at a time');
8362: #   Limits (ordered: label -> its group's limit, roster order) }
8363: function Get-PanelPlan {
8364:     param([object[]]$Runners, [hashtable]$Parallel = $null, [int]$Cap = 0)
8365:     $eg = Get-EndpointGroups -Members $Runners -Scheduling
8366:     $effective = 0
8367:     $limits = [ordered]@{}
8368:     $out = New-Object System.Collections.Generic.List[object]
8369:     foreach ($g in $eg.Groups) {
8370:         $limit = 0
8371:         foreach ($l in $g.Labels) {
8372:             $v = 1
8373:             if ($null -ne $Parallel -and $Parallel.ContainsKey($l)) { $v = [int]$Parallel[$l] }
8374:             if ($limit -eq 0 -or $v -lt $limit) { $limit = $v }
8375:         }
8376:         $effective += [Math]::Min($limit, $g.Positions.Count)
8377:         $out.Add([pscustomobject]@{ Labels = [string[]]$g.Labels.ToArray(); Limit = $limit; Positions = [int[]]$g.Positions.ToArray() })
8378:     }
8379:     foreach ($l in $eg.Labels) { $limits[$l] = $out[$eg.IndexOfLabel[$l]].Limit }
8380:     if ($Cap -gt 0 -and $Cap -lt $effective) { $effective = $Cap }
8381:     $count = @($Runners | Where-Object { $_ }).Count
8382:     $text = if ($effective -ge $count) { 'at once' } elseif ($effective -le 1) { 'one after another' } else { "at most $effective at a time" }
8383:     return [pscustomobject]@{ Groups = [object[]]$out.ToArray(); GroupOf = $eg.GroupOf; Cap = $Cap; Effective = $effective; Text = $text; Limits = $limits }
8384: }
